import{c as a,Q as e,j as r,m as s}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"用 Fable 5 构建自我改进的智能体系统：14 步实现循环、动态工作流和例程","description":"","frontmatter":{"url":"https://x.com/servasyy_ai/status/2065594120748597508","title":"用 Fable 5 构建自我改进的智能体系统：14 步实现循环、动态工作流和例程","author":"servasyy_ai","archived":"2026-07-03T00:00:00.000Z","handle":"@servasyy_ai","published":"2026-06-13T00:00:00.000Z","stats":"79 likes · 19 retweets · 222 bookmarks · 62507 views","tags":["fable5","self-improving","memory-stages","state-files","skills","orchestration","maker-verifier","worktrees","routines","model-routing","zh-cn"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-13-@servasyy_ai-597508.md","filePath":"research/tweets/2026-06-13-@servasyy_ai-597508.md","lastUpdated":1785909234000}'),i={name:"research/tweets/2026-06-13-@servasyy_ai-597508.md"};function l(n,t,o,d,h,g){return e(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="用-fable-5-构建自我改进的智能体系统-14-步实现循环、动态工作流和例程-—-servasyy-ai" tabindex="-1">用 Fable 5 构建自我改进的智能体系统：14 步实现循环、动态工作流和例程 — @servasyy_ai <a class="header-anchor" href="#用-fable-5-构建自我改进的智能体系统-14-步实现循环、动态工作流和例程-—-servasyy-ai" aria-label="Permalink to &quot;用 Fable 5 构建自我改进的智能体系统：14 步实现循环、动态工作流和例程 — @servasyy_ai&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/servasyy_ai/status/2065594120748597508" target="_blank" rel="noreferrer">https://x.com/servasyy_ai/status/2065594120748597508</a><strong>作者</strong>：servasyy_ai（@servasyy_ai） <strong>發布日期</strong>：2026-06-13 <strong>收錄日期</strong>：2026-07-03 <strong>類型</strong>：Twitter Article（簡體中文） <strong>統計</strong>：79 likes · 19 retweets · 222 bookmarks · 62507 views</p><hr><h2 id="全文摘要" tabindex="-1">全文摘要 <a class="header-anchor" href="#全文摘要" aria-label="Permalink to &quot;全文摘要&quot;">​</a></h2><p><strong>定位</strong>：14 步構建 Fable 5「自我改進系統」的完整路線圖，三層架構（原語層／Orchestration 層／Self-improvement 層）+ Memory 五階段進化模型 + Maker/Verifier 分離原則，含 Anthropic Parameter Golf 實驗數據。</p><h3 id="核心概念澄清" tabindex="-1">核心概念澄清 <a class="header-anchor" href="#核心概念澄清" aria-label="Permalink to &quot;核心概念澄清&quot;">​</a></h3><p><strong>Self-improving ≠ Self-learning</strong></p><ul><li>Self-learning（不是 Fable 5 做的事）：模型改變自己的權重，變得更聰明</li><li>Self-improving（Fable 5 的實際方式）：模型本身不變，但周圍系統（Memory/Skills/Workflow）持續積累優化</li><li>「模型是無狀態的，但系統是有狀態的」</li></ul><h3 id="四層架構-複利增長" tabindex="-1">四層架構（複利增長） <a class="header-anchor" href="#四層架構-複利增長" aria-label="Permalink to &quot;四層架構（複利增長）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>層次</th><th>內容</th><th>類比</th></tr></thead><tbody><tr><td><strong>第 1 層（原語層）</strong></td><td>Fable 5 模型、基礎工具、簡單對話</td><td>厲害員工但無工作流程/模板/標準</td></tr><tr><td><strong>第 2 層（Orchestration 層）</strong></td><td>/goal、動態 Workflow、Routines</td><td>配備項目管理工具和自動化腳本</td></tr><tr><td><strong>第 3 層（Memory 層）</strong></td><td>STATE.md、Skills 庫、知識庫</td><td>筆記本、工作手冊、經驗總結</td></tr><tr><td><strong>第 4 層（Self-improvement 層）</strong></td><td>自我檢查輸出→提炼教訓→寫回 Skills→閉環</td><td>員工反思更新工作手冊，能力複利增長</td></tr></tbody></table><h3 id="四模型路由-成本控制" tabindex="-1">四模型路由（成本控制） <a class="header-anchor" href="#四模型路由-成本控制" aria-label="Permalink to &quot;四模型路由（成本控制）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>角色</th><th>使用場景</th><th>成本</th></tr></thead><tbody><tr><td><strong>Fable 5</strong></td><td>項目經理（Orchestrator）</td><td>複雜多天項目、整體規劃</td><td>$$$</td></tr><tr><td><strong>Opus 4.8</strong></td><td>技術專家（Fallback）</td><td>架構決策、複雜調試</td><td>$$</td></tr><tr><td><strong>Sonnet 4.6</strong></td><td>Worker</td><td>日常代碼、重構、文檔</td><td>$</td></tr><tr><td><strong>Haiku 4.5</strong></td><td>Grader</td><td>快速驗證、簡單分類</td><td>$</td></tr></tbody></table><p><strong>黃金組合</strong>：<code>Fable 5 Orchestrator + Sonnet Worker + Haiku Grader + Opus Fallback</code>（Anthropic 內部使用）</p><h3 id="三個-primitives-讓系統「活」起來" tabindex="-1">三個 Primitives（讓系統「活」起來） <a class="header-anchor" href="#三個-primitives-讓系統「活」起來" aria-label="Permalink to &quot;三個 Primitives（讓系統「活」起來）&quot;">​</a></h3><p><strong>05 · Loop 機制（/goal + Outcomes）</strong></p><ul><li>設定明確 Goal → 獨立 Grader 檢查 → 未達標自動下一輪優化 → 達標退出</li><li><code>/goal</code>（Claude Code 本地）vs <code>Outcomes</code>（CMA 雲端，適合 GPU/Sandbox 任務）</li></ul><p><strong>06 · Maker/Verifier 分離（強制要求）</strong></p><ul><li>Anthropic Parameter Golf 實驗：有獨立 Verifier 的 Fable 5 → 約 6 倍於 Opus 4.7 的改進</li><li>無 Verifier 的 Opus 4.7 → 保守小改動，遇負面結果即停</li><li>有 Verifier 的 Fable 5 → 敢於大膽架構改變，持續探索直至最優</li></ul><p><strong>07 · 動態工作流（三種模式）</strong></p><ol><li><strong>Fan-out and Synthesize</strong>：大任務拆分平行，綜合結果（20 個規則 → 20 個平行 Verification Agent）</li><li><strong>Adversarial Verification</strong>：自動生成「攻擊者 Agent」找 Bug，完全不知道 Maker 思路</li><li><strong>Loop Until Done</strong>：跑測試→失敗分析修復→再跑，循環直到全通過</li></ol><p><strong>08 · Git Worktrees（防文件衝突）</strong></p><ul><li>多 Agent 並行時，各 Agent 在獨立 worktree 工作，完成後合並</li><li>場景：Maker/Verifier 隔離 / 並行實驗 / 長期項目 Checkpoints</li></ul><p><strong>09 · Routines（三種觸發方式）</strong></p><ul><li><strong>Scheduled Triggers</strong>：每天定時自動運行（重跑測試、更新 Skills、發 Slack 摘要）</li><li><strong>API Triggers</strong>：CI 失敗/服務報警時自動響應</li><li><strong>GitHub Triggers</strong>：PR 提交/合並後自動評估/提炼模式到 Skills 庫</li></ul><h3 id="memory-五階段進化模型" tabindex="-1">Memory 五階段進化模型 <a class="header-anchor" href="#memory-五階段進化模型" aria-label="Permalink to &quot;Memory 五階段進化模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>階段</th><th>名稱</th><th>行動</th><th>例子</th></tr></thead><tbody><tr><td><strong>Stage 1</strong></td><td>Failure</td><td>記錄失敗</td><td>「查詢返回空結果」</td></tr><tr><td><strong>Stage 2</strong></td><td>Investigation</td><td>追根溯源</td><td>「字段名錯了，用了 prc_usd 但實際是 prc」</td></tr><tr><td><strong>Stage 3</strong></td><td>Verification</td><td>確認已驗證事實</td><td><code>SELECT MIN(prc), MAX(prc) FROM trades</code> 確認字段</td></tr><tr><td><strong>Stage 4</strong></td><td>Distillation</td><td>提炼通用規則</td><td>「查詢時間分桶時始終指定時區」</td></tr><tr><td><strong>Stage 5</strong></td><td>Consultation</td><td>下次主動查閱規則</td><td>再次查詢時自動應用「時區規則」</td></tr></tbody></table><p><strong>各模型實驗數據（Anthropic）</strong>：</p><ul><li>Sonnet 4.6：停在 Stage 1（記錄失敗，不深入調查）</li><li>Opus 4.7：到達 Stage 3，驗證覆蓋率 17%（30 個問題中驗證 5 個）</li><li>Fable 5：完成全部五階段，驗證覆蓋率 73%（30 個問題中驗證 22 個）</li></ul><h3 id="state-md-結構-六分區" tabindex="-1">STATE.md 結構（六分區） <a class="header-anchor" href="#state-md-結構-六分區" aria-label="Permalink to &quot;STATE.md 結構（六分區）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 項目記憶 · [項目名]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 已驗證的事實（Stage 3 — 不再猜測這些）</span></span>
<span class="line"><span>- 欄位/數值/配置，附驗證命令和確認日期</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 通用規則（Stage 4 — 先查閱再行動）</span></span>
<span class="line"><span>- 可應用到其他場景的原則</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 待調查的失敗（Stage 1→2）</span></span>
<span class="line"><span>- 已知失敗 + 假設 + 重現步驟</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 經驗教訓（Stage 4 的提煉）</span></span>
<span class="line"><span>- 踩坑記錄 + 解決方案</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 上次會話（Stage 5 — 恢復點）</span></span>
<span class="line"><span>- 時間戳 + 已完成 + 下一步</span></span></code></pre></div><p><strong>兩個黃金規則</strong>：① 離開前必須寫入；② 開始前必須讀取</p><h3 id="state-md-vs-skills-分工" tabindex="-1">STATE.md vs Skills 分工 <a class="header-anchor" href="#state-md-vs-skills-分工" aria-label="Permalink to &quot;STATE.md vs Skills 分工&quot;">​</a></h3><table tabindex="0"><thead><tr><th>類型</th><th>範圍</th><th>生命週期</th><th>例子</th></tr></thead><tbody><tr><td><strong>STATE.md</strong></td><td>項目特定</td><td>隨項目結束</td><td>「這個項目的 prc 字段是美元」</td></tr><tr><td><strong>Skills</strong></td><td>跨項目通用</td><td>永久（<code>~/.claude/skills/</code>）</td><td>「處理價格字段時，始終驗證單位」</td></tr></tbody></table><h3 id="visual-verification-視覺驗證" tabindex="-1">Visual Verification（視覺驗證） <a class="header-anchor" href="#visual-verification-視覺驗證" aria-label="Permalink to &quot;Visual Verification（視覺驗證）&quot;">​</a></h3><ul><li>Fable 5 可截圖→視覺能力「看」截圖→對照設計要求→描述具體差距→返回 Maker</li><li>適用場景：UI 實現驗證、數據可視化、設計保真度檢查</li><li>Parameter Golf 實驗：Fable 5 自己看訓練曲線圖判斷是否收斂，無需人類看圖表</li></ul><h3 id="safety-boundaries-安全分類器" tabindex="-1">Safety Boundaries（安全分類器） <a class="header-anchor" href="#safety-boundaries-安全分類器" aria-label="Permalink to &quot;Safety Boundaries（安全分類器）&quot;">​</a></h3><p>分類器觸發後返回 HTTP 200（<code>stop_reason: &quot;refusal&quot;</code>，非 HTTP 錯誤）：</p><ul><li>網絡安全漏洞研究</li><li>生物學</li><li>化學</li><li>模型蒸餾</li></ul><p><strong>設計原則</strong>：必須為這些域設計 fallback 機制 + 不同 Agent 進行安全分析 + 測試用無害替代品</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Fable 5 「自我改進系統」完整 14 步路線圖（簡中）：Self-improving≠Self-learning 澄清、四層架構、四模型路由（Orchestrator/Expert/Worker/Grader）、Memory 五階段進化（Failure→Distillation→Consultation）、STATE.md 六分區模板、Skills vs STATE.md 分工、Maker/Verifier 分離（+6x 改進數據）、三種 Routine 觸發方式、Git Worktrees 隔離、Visual Verification、Safety Boundary 設計。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>Self-improving ≠ Self-learning</strong>：模型無狀態，系統有狀態——Memory/Skills 積累才是複利增長的本質</li><li><strong>Memory 五階段</strong>：Sonnet=Stage1/Opus=Stage3(17%)/Fable=Stage5(73%)——驗證覆蓋率差距體現在 Stage3 Verification</li><li><strong>Maker/Verifier 分離</strong>：結構性分離（不同 Agent、不同 worktree、不同上下文）產生 6x 改進</li><li><strong>STATE.md 是恢復點</strong>：沒有「開始前讀取」→ Fable 5 退化到 Sonnet 級別記憶表現</li><li><strong>四模型路由</strong>：Fable 5 最貴，只用於需要多天持續協調的任務</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Parameter Golf 實驗：8×H100，8 小時，Fable 5 with Verifier = 6x 改進 vs Opus 4.7</li><li>Memory 驗證覆蓋率：Sonnet≈0%、Opus 4.7=17%、Fable 5=73%</li><li>STATE.md 六分區模板 + CI triage Skills 演化範例</li><li>三種 Routine 觸發（Scheduled/API/GitHub）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>Memory 五階段模型（Stage1~5）與 workspace 的 MEMORY.md + LESSONS.md 分工高度對齊</li><li>Maker/Verifier 分離強化 subagent-strategy.md 的「child 不 self-retry」原則</li><li>STATE.md 六分區結構可作為 MEMORY.md 的項目級模板補充</li><li>四模型路由 Grader 角色（Haiku 做快速驗證）補充 delegation-protocol.md</li><li>Safety classifier fallback 設計原則補充 error-handling 規範</li><li>文章為簡體中文，受眾為中文用戶；內容原創性高，大量引用 Anthropic 官方實驗數據</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>STATE.md 模板、Skills/STATE 分工、四模型路由、Maker/Verifier 分離、Routine 觸發設計可直接套用</td></tr><tr><td>B. 創新性 (20%)</td><td>7.5/10</td><td>Self-improving≠Self-learning 明確澄清；Memory 五階段模型（附驗證率數據）；State Files 六分區結構；6x 改進量化</td></tr><tr><td>C. 證據品質 (20%)</td><td>8/10</td><td>Anthropic Parameter Golf 實驗（8×H100，8h）；三模型驗證覆蓋率（0%/17%/73%）；6x 改進數字有具體出處</td></tr><tr><td>D. 技術深度 (15%)</td><td>8/10</td><td>STATE.md 完整模板、CI triage skill 兩週演化範例、Git Worktrees 用途、三種 Routine 觸發、Safety classifier 四域</td></tr><tr><td>E. 泛化性 (15%)</td><td>7.5/10</td><td>不限 Fable 5；Memory/Skills/Verification 模式跨模型適用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.8/10</strong></td><td>8×0.3+7.5×0.2+8×0.2+8×0.15+7.5×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：Memory 五階段模型補充 MEMORY.md 維護協議；STATE.md 六分區模板可作為項目級記憶模板；Maker/Verifier 強制分離補充 subagent-strategy.md；四模型路由 Grader 角色補充 delegation-protocol.md；Safety classifier fallback 補充 error-handling。</p>`,52)])])}const u=a(i,[["render",l]]);export{c as __pageData,u as default};
